#!/usr/bin/env python3
"""build the C oracle for IQ4_XS/IQ3_S from llama.cpp's own source text.

the port's oracle is the incumbent's decoder, so this does not re-express the
algorithm: it lifts `dequantize_row_iq4_xs` and `dequantize_row_iq3_s` verbatim
out of `ggml-quants.c` and the codebooks out of `ggml-common.h`, then compiles
them. `GGML_FP16_TO_FP32` is the only thing supplied locally (a standard IEEE
half-to-float conversion in `ggml.c`), and it is not part of what is compared.

usage: iql_oracle.py <llama.cpp-root> <fixture-dir> <cc>
"""
import pathlib
import re
import subprocess
import sys

FUNCTIONS = ["dequantize_row_iq4_xs", "dequantize_row_iq3_s"]


def extract_function(source, name):
    start = source.index(f"void {name}(")
    end = source.index("\n}\n", start) + len("\n}\n")
    return source[start:end]


def main():
    llama_root = pathlib.Path(sys.argv[1])
    fixture_dir = pathlib.Path(sys.argv[2])
    cc = sys.argv[3] if len(sys.argv) > 3 else "cc"

    quants = (llama_root / "ggml/src/ggml-quants.c").read_text()
    bodies = "\n".join(extract_function(quants, name) for name in FUNCTIONS)

    oracle = "\n".join(
        [
            "/* generated by iql_oracle.py from llama.cpp; do not edit */",
            "#define GGML_COMMON_DECL_C",
            "#define GGML_COMMON_IMPL_C",
            '#include "ggml-common.h"',
            "#include <assert.h>",
            "#include <stdint.h>",
            "#include <stdio.h>",
            "#include <stdlib.h>",
            "#include <string.h>",
            "",
            "/* ggml.c's ggml_fp16_to_fp32; not part of the comparison */",
            "static inline float iql_fp32_from_bits(uint32_t w) {",
            "    float value;",
            "    __builtin_memcpy(&value, &w, sizeof(value));",
            "    return value;",
            "}",
            "static inline uint32_t iql_fp32_to_bits(float f) {",
            "    uint32_t w;",
            "    __builtin_memcpy(&w, &f, sizeof(w));",
            "    return w;",
            "}",
            "static float fp16_to_fp32(ggml_half h) {",
            "    const uint32_t w = (uint32_t) h << 16;",
            "    const uint32_t sign = w & UINT32_C(0x80000000);",
            "    const uint32_t two_w = w + w;",
            "    const uint32_t exp_offset = UINT32_C(0xE0) << 23;",
            "    const float exp_scale = 0x1.0p-112f;",
            "    const float normalized_value =",
            "        iql_fp32_from_bits((two_w >> 4) + exp_offset) * exp_scale;",
            "    const uint32_t magic_mask = UINT32_C(126) << 23;",
            "    const float magic_bias = 0.5f;",
            "    const float denormalized_value =",
            "        iql_fp32_from_bits((two_w >> 17) | magic_mask) - magic_bias;",
            "    const uint32_t denormalized_cutoff = UINT32_C(1) << 27;",
            "    const uint32_t result = sign |",
            "        (two_w < denormalized_cutoff ?",
            "             iql_fp32_to_bits(denormalized_value) :",
            "             iql_fp32_to_bits(normalized_value));",
            "    return iql_fp32_from_bits(result);",
            "}",
            "#undef GGML_FP16_TO_FP32",
            "#define GGML_FP16_TO_FP32(x) fp16_to_fp32(x)",
            "#define GGML_RESTRICT",
            "",
            bodies,
            "",
            "int main(int argc, char ** argv) {",
            "    if (argc != 3) {",
            "        fprintf(stderr, \"usage: %s <blocks.bin> <iq4_xs|iq3_s>\\n\", argv[0]);",
            "        return 2;",
            "    }",
            "    const char * kind = argv[2];",
            "    FILE * file = fopen(argv[1], \"rb\");",
            "    if (!file) { perror(\"open\"); return 1; }",
            "    fseek(file, 0, SEEK_END);",
            "    const long size = ftell(file);",
            "    fseek(file, 0, SEEK_SET);",
            "    uint8_t * bytes = malloc((size_t) size);",
            "    if (fread(bytes, 1, (size_t) size, file) != (size_t) size) { return 1; }",
            "    fclose(file);",
            "    const int is_iq4_xs = strcmp(kind, \"iq4_xs\") == 0;",
            "    const int block_bytes = is_iq4_xs ? 136 : 110;",
            "    const int blocks = (int) (size / block_bytes);",
            "    float * out = malloc((size_t) blocks * QK_K * sizeof(float));",
            "    if (is_iq4_xs) {",
            "        dequantize_row_iq4_xs((const block_iq4_xs *) bytes, out, blocks * QK_K);",
            "    } else {",
            "        dequantize_row_iq3_s((const block_iq3_s *) bytes, out, blocks * QK_K);",
            "    }",
            "    for (int i = 0; i < blocks * QK_K; ++i) {",
            "        uint32_t bits;",
            "        __builtin_memcpy(&bits, &out[i], sizeof(bits));",
            "        printf(\"%08x%s\", bits, (i + 1) % 16 == 0 ? \"\\n\" : \" \");",
            "    }",
            "    return 0;",
            "}",
        ]
    )

    c_path = fixture_dir / "iql_oracle.c"
    c_path.write_text(oracle)
    binary = fixture_dir / "iql_oracle"
    subprocess.run(
        [cc, "-O2", "-I", str(llama_root / "ggml/src"), "-o", str(binary), str(c_path)],
        check=True,
    )
    print(f"built {binary}")


if __name__ == "__main__":
    main()
